cssStarter:
:root{--primary:#062462;--accent:#da242b;--ink:#062461;--body:#616161;--surface:#ffffff;--surface-alt:#f6f6f6;--footer:#052361;--container:1280px;--gutter:32px;--section-y:88px}
body{font-family:'Poppins',sans-serif;font-size:15px;line-height:1.87;color:var(--body)}
.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0 70px}
h1,h2,h3,h4{font-family:'Inter',sans-serif;color:var(--ink)}
h2 em,h1 em{font-style:normal;color:var(--accent)}
.eyebrow{font-family:'Inter',sans-serif;font-size:16px;font-weight:500;line-height:1.2;text-transform:uppercase;color:var(--accent);margin-bottom:14px}
.hero-title{font-size:58px;font-weight:800;line-height:1.12;text-transform:uppercase;color:var(--primary)}
h2{font-size:40px;font-weight:700;line-height:1.25;margin:0}
h3{font-size:22px;font-weight:600;line-height:1.2}
.btn{position:relative;display:inline-flex;align-items:center;height:60px;padding:0 42px;border-radius:5px 30px 30px 5px;font-size:15px;font-weight:500;background:var(--primary);color:#fff}
.btn::after{content:'+';position:absolute;right:-12px;top:50%;transform:translateY(-50%);width:24px;height:24px;border-radius:50%;background:#fff;color:var(--primary);border:2px solid var(--primary);display:grid;place-items:center;font-size:14px;line-height:1}
.btn-accent{background:var(--accent);border-radius:5px;height:52px;padding:0 35px}
.btn-accent::after{display:none}
.panel{background:#fff;border-radius:10px;box-shadow:0 20px 60px rgba(6,36,98,.12);padding:80px}
.house-badge{width:84px;height:96px;background:var(--accent);clip-path:polygon(50% 0,100% 42%,88% 42%,88% 100%,12% 100%,12% 42%,0 42%);display:grid;place-items:end center;padding-bottom:14px;color:#fff}
@media(max-width:768px){:root{--section-y:64px}.hero-title{font-size:36px}h2{font-size:30px}.panel{padding:32px 20px}}
